calculator.mjs.text:
/**
 * Newsletter sponsorship rate calculator, as a deterministic module.
 *
 * Newsletter sponsorship marketplaces (Swapstack, Paved, Sponsy) and
 * creator-economy write-ups routinely quote ad prices as a CPM against
 * *opens*, not raw subscriber count -- a sponsor is paying for eyes on the
 * ad, and open rate is the one number that separates a list of 20,000
 * mostly-dormant addresses from a list of 5,000 people who read every
 * issue. This module applies commonly cited benchmark CPM-per-1000-opens
 * ranges, by niche and by placement, to a newsletter's own numbers and
 * returns a price *range* per placement -- a starting point for
 * negotiation, never a quote or a valuation performed on the user's
 * behalf. See index.html's disclaimer for the exact wording.
 *
 * Benchmark ranges are deliberately wide and clearly labeled as general
 * market ranges rather than a specific quote: actual rates vary by list
 * quality, click-through history, and how badly a given sponsor wants that
 * audience on that week.
 */

export const PLACEMENTS = ["dedicated", "primary", "secondary", "classified"];

export const PLACEMENT_LABELS = {
  dedicated: "Dedicated send (solo email, just the ad)",
  primary: "Primary in-issue placement (top ad slot)",
  secondary: "Secondary in-issue placement (lower ad slot)",
  classified: "Classified / text-link placement",
};

export const NICHES = ["general", "tech", "finance", "b2b"];

export const NICHE_LABELS = {
  general: "General interest / lifestyle",
  tech: "Tech / SaaS / startups",
  finance: "Finance / business / investing",
  b2b: "B2B / niche professional",
};

// Commonly cited CPM-per-1000-opens ranges [low, high], USD, by niche and
// placement. Deliberately wide: these are general market ranges to anchor
// a negotiation, not a quote for any specific list.
const CPM_PER_1000_OPENS = {
  general: { dedicated: [30, 50], primary: [20, 35], secondary: [12, 20], classified: [6, 10] },
  tech: { dedicated: [40, 70], primary: [25, 45], secondary: [15, 25], classified: [8, 12] },
  finance: { dedicated: [50, 90], primary: [35, 55], secondary: [20, 30], classified: [10, 15] },
  b2b: { dedicated: [45, 80], primary: [30, 50], secondary: [18, 28], classified: [9, 14] },
};

export const SEVERITY = { HIGH: "high", MEDIUM: "medium", LOW: "low", INFO: "info" };

function round(n) {
  return Math.round(n);
}

/**
 * @param {{subscribers: number, openRate: number, niche: string}} input
 * @returns {{opens: number, rates: Record<string, {low:number, high:number}>, findings: Array<{id:string, severity:string, title:string, detail:string}>}}
 */
export function computeRates({ subscribers, openRate, niche }) {
  const subs = Number.isFinite(subscribers) && subscribers > 0 ? subscribers : 0;
  const rate = Number.isFinite(openRate) && openRate > 0 ? Math.min(openRate, 100) : 0;
  const key = NICHES.includes(niche) ? niche : "general";

  const opens = subs * (rate / 100);
  const perThousandOpens = opens / 1000;

  const rates = {};
  for (const placement of PLACEMENTS) {
    const [cpmLow, cpmHigh] = CPM_PER_1000_OPENS[key][placement];
    rates[placement] = {
      cpmLow,
      cpmHigh,
      low: round(perThousandOpens * cpmLow),
      high: round(perThousandOpens * cpmHigh),
    };
  }

  const findings = [];

  if (subs === 0 || rate === 0) {
    findings.push({
      id: "missing-input",
      severity: SEVERITY.INFO,
      title: "Enter your subscriber count and open rate",
      detail: "Both numbers come from your own newsletter platform's dashboard (Substack, beehiiv, ConvertKit, Mailchimp, and others all report both). Prices below are all zero until real numbers are entered.",
    });
    return { opens, rates, findings };
  }

  if (subs < 1000) {
    findings.push({
      id: "small-list",
      severity: SEVERITY.MEDIUM,
      title: "Under 1,000 subscribers is below many sponsors' minimum",
      detail: "Several newsletter ad marketplaces set an audience floor (often 1,000-2,500 subscribers) before listing a newsletter at all. Below that size, direct outreach to a sponsor whose audience you clearly overlap with usually works better than a posted rate card.",
    });
  }

  if (rate < 15) {
    findings.push({
      id: "low-open-rate",
      severity: SEVERITY.MEDIUM,
      title: "Open rate is below the range sponsors usually expect",
      detail: "A sub-15% open rate is low relative to typical email newsletter benchmarks and will make a sponsor discount the subscriber count heavily regardless of the price you quote. Since these prices are already calculated from opens rather than raw subscribers, they already account for this — but a sponsor evaluating your list from the outside may still ask why the open rate is low.",
    });
  } else if (rate > 70) {
    findings.push({
      id: "high-open-rate",
      severity: SEVERITY.INFO,
      title: "Open rate is unusually high",
      detail: "Above ~70% is unusual outside a very small or highly engaged list. That is a genuine selling point worth naming explicitly to a sponsor — highly engaged small lists often out-convert larger, more passive ones — but double-check the number against your platform's own reporting period before quoting it.",
    });
  }

  return { opens, rates, findings };
}

handoff.mjs.text:
// Carry the rates you just calculated into the media-kit builder.
//
// Same move as `ventures/brand-deal-rate-calculator/handoff.mjs`, for the
// other half of the same creator's business. `influencer-media-kit-generator`
// warns on "No platforms listed" and "No rate card"; this page has just
// computed both, for a newsletter rather than a social account.
//
// The two senders compose rather than compete, and that is the point of the
// receiver being append-only: an operator with an Instagram audience *and* a
// list follows both links and ends up with one kit carrying two reach rows and
// eight rate rows, instead of one overwriting the other.
//
// This is a sibling of that module, not a copy of it — the fields, the labels
// and the metric all differ, because a newsletter is priced per thousand opens
// rather than per thousand engaged followers. What must NOT drift between them
// is the wire contract: the same two target field names, the same fragment
// (never query) URL shape, the same relative link. `handoff.test.mjs` imports
// the other venture's module and asserts exactly that, so a change to either
// side fails a test rather than quietly producing two incompatible links.

import { NICHE_LABELS, NICHES, PLACEMENTS } from "./calculator.mjs";

/** The tool this page hands off to. Field names are the receiving form's own. */
export const HANDOFF = Object.freeze({
  slug: "influencer-media-kit-generator",
  label: "media kit generator",
  platformsField: "platformsRaw",
  ratesField: "ratesRaw",
});

/**
 * Rate-card wording for each placement.
 *
 * `PLACEMENT_LABELS` in `calculator.mjs` explains the *distinction* to someone
 * choosing between rows ("Primary in-issue placement (top ad slot)"); a rate
 * card a sponsor reads wants the short name. Kept as its own table rather than
 * derived by trimming the parenthetical, because that would be a formatting
 * rule pretending to be a translation. `handoff.test.mjs` asserts every id in
 * `PLACEMENTS` has an entry, so a placement added to the calculator cannot
 * silently vanish from the kit.
 */
const RATE_CARD_PLACEMENT = Object.freeze({
  dedicated: "Newsletter dedicated send",
  primary: "Newsletter primary placement",
  secondary: "Newsletter secondary placement",
  classified: "Newsletter classified / text link",
});

/** The service name for one rate-card row, or null for an unknown placement. */
export function rateCardService(placement) {
  return RATE_CARD_PLACEMENT[placement] ?? null;
}

/** `$380 - $620` — the sign outside the symbol, and no sign on a zero, per
 * `platform/ci/check_money_sign.py` and this page's own `money()`. */
export function formatRange(low, high) {
  const money = (value) => {
    const format = (n) => `$${Math.round(n).toLocaleString("en-US")}`;
    const text = format(Math.abs(value));
    return value < 0 && /[1-9]/.test(text) ? `-${text}` : text;
  };
  return `${money(low)} – ${money(high)}`;
}

/** `42.5` rather than `42.500000001`, and `42` rather than `42.0`. */
function trimRate(rate) {
  return String(Math.round(rate * 100) / 100);
}

/**
 * The reach line, in the receiver's `platform | followers | engagement | url`
 * format.
 *
 * The metric is named — `42% open`, not a bare `42%`. The receiver appends the
 * word "engagement" to a bare number, which is right for a social account and
 * wrong for a list: an open rate is not an engagement rate, and a sponsor
 * reading "42% engagement" on a newsletter row would reasonably take it for a
 * click rate. `engagementLabel` in `generator.mjs` leaves a value that names
 * its own metric alone, which is what makes this honest rather than clunky.
 *
 * The niche rides in the platform name, because it is what the rate was priced
 * against and a sponsor comparing two newsletters at the same size wants to
 * see it. No URL: this page never asks for one.
 */
export function buildPlatformsBlock({ subscribers, openRate, niche }) {
  const subs = Number(subscribers);
  const rate = Number(openRate);
  if (!Number.isFinite(subs) || subs <= 0) return "";
  if (!Number.isFinite(rate) || rate <= 0) return "";
  const key = NICHES.includes(niche) ? niche : "general";
  const name = key === "general" ? "Newsletter" : `Newsletter (${NICHE_LABELS[key]})`;
  // Plain digits, not `toLocaleString`: a kit built from a handoff and one
  // typed by hand should not differ by a comma.
  return `${name} | ${Math.round(subs)} | ${trimRate(rate)}% open`;
}

/**
 * The rate-card block, one line per placement, `service | price`.
 *
 * The range travels, not a point estimate — this page says its output starts a
 * negotiation and is never a quote, and collapsing it on the way into a
 * document a sponsor reads would make a claim the tool refuses to make.
 */
export function buildRatesBlock({ rates }) {
  if (!rates || typeof rates !== "object") return "";
  const lines = [];
  for (const placement of PLACEMENTS) {
    const row = rates[placement];
    if (!row) continue;
    const { low, high } = row;
    if (!Number.isFinite(low) || !Number.isFinite(high)) continue;
    // Zero means the numbers above were never entered. "$0 - $0" in a rate
    // card a sponsor reads is worse than no row.
    if (high <= 0) continue;
    const service = rateCardService(placement);
    if (!service) continue;
    lines.push(`${service} | ${formatRange(low, high)}`);
  }
  return lines.join("\n");
}

/** What to hand over, keyed by the receiving form's field ids, or null. */
export function buildHandoffFields(input = {}, result = {}) {
  const platformsRaw = buildPlatformsBlock(input);
  const ratesRaw = buildRatesBlock({ rates: result.rates });
  if (!platformsRaw && !ratesRaw) return null;
  const out = {};
  if (platformsRaw) out[HANDOFF.platformsField] = platformsRaw;
  if (ratesRaw) out[HANDOFF.ratesField] = ratesRaw;
  return out;
}

/**
 * A relative link to the media kit generator, carrying the rate card, or null
 * when there is nothing to carry.
 *
 * Relative so it works under the GitHub Pages project path, under a custom
 * domain later, and from a local static server. The values ride in the
 * fragment, which browsers do not send to any server.
 */
export function handoffUrl(input = {}, result = {}) {
  const fields = buildHandoffFields(input, result);
  if (!fields) return null;
  const params = new URLSearchParams();
  for (const field of Object.keys(fields).sort()) params.set(field, fields[field]);
  return `../${HANDOFF.slug}/#${params.toString()}`;
}

share.mjs.text:
import { NICHES } from "./calculator.mjs";

/**
 * The inputs a link carries: the three `computeRates` reads.
 *
 * Two of them are numbers and one is an enum, which is why this module cannot
 * be the same shape as the portfolio's all-numeric `share.mjs` modules. The
 * enum is validated against `NICHES` — imported, never restated — so a link
 * carrying an unknown niche falls back to the page's own default rather than
 * putting an unrecognised value into the form and pricing against nothing.
 */
export const NUMERIC_FIELDS = Object.freeze(["subscribers", "openRate"]);
export const SHARE_FIELDS = Object.freeze([...NUMERIC_FIELDS, "niche"]);

export function encodeInputs(input) {
  const params = new URLSearchParams();
  for (const field of NUMERIC_FIELDS) {
    // Blank is a real state here: the page opens with both boxes empty and
    // shows its "enter your numbers" prompt rather than a rate card, so a
    // sender who cleared a box should not have it silently refilled.
    if (input?.[field] === "") {
      params.set(field, "");
      continue;
    }
    const value = Number(input?.[field]);
    if (Number.isFinite(value) && value >= 0) params.set(field, String(value));
  }
  if (NICHES.includes(input?.niche)) params.set("niche", input.niche);
  return params.toString();
}

export function decodeInputs(value) {
  const params = new URLSearchParams(String(value || "").replace(/^[?#]/, ""));
  const result = {};
  for (const field of NUMERIC_FIELDS) {
    if (!params.has(field)) continue;
    if (params.get(field) === "") {
      result[field] = "";
      continue;
    }
    const number = Number(params.get(field));
    if (Number.isFinite(number) && number >= 0) result[field] = number;
  }
  // An unknown niche is dropped rather than carried. The form is a <select>,
  // so writing a value it has no <option> for would leave the control showing
  // its first option while the link claimed another -- the two-people-reading-
  // different-numbers failure this whole module exists to avoid.
  if (NICHES.includes(params.get("niche"))) result.niche = params.get("niche");
  return result;
}

/**
 * Every field the form owns, written whether or not the link carried it, so a
 * box the sender cleared arrives cleared. `niche` falls back to the page's
 * shipped default because a <select> has no blank option to fall back to.
 *
 * See `platform/ci/check_shared_link_clears.py`.
 */
export function formValues(decoded, defaultNiche = NICHES[0]) {
  const values = Object.fromEntries(
    NUMERIC_FIELDS.map(field => [field, decoded?.[field] !== undefined ? String(decoded[field]) : ""]),
  );
  values.niche = NICHES.includes(decoded?.niche) ? decoded.niche : defaultNiche;
  return values;
}

usage.mjs.text:
const KEY = "newsletter-sponsorship-rate-calculator-usage";
// Separate from the counters on purpose: opting out *removes* the
// counters, so a flag stored inside them would be deleted by the very
// act it records.
const OPT_OUT = "newsletter-sponsorship-rate-calculator-usage-opt-out";

// The in-memory flag is only a same-page fast path. `globalThis` is a
// fresh realm on every page load, so without the stored key the switch
// silently stops working on the visitor's next visit -- and they do not
// look again, because they believe they already used it.
function usageOptedOut() {
  if (globalThis.__usageOptOut) return true;
  try {
    return typeof localStorage !== "undefined" && localStorage.getItem(OPT_OUT) === "1";
  } catch {
    // A blocked or full store must never be read as consent.
    return false;
  }
}

function usageBlocked() {
  if (usageOptedOut()) return true;
  try {
    if (navigator.doNotTrack === "1" || navigator.globalPrivacyControl) return true;
  } catch {
    /* navigator is optional in tests */
  }
  return false;
}

export function record(event) {
  if (typeof localStorage === "undefined" || usageBlocked()) return;
  let current;
  try {
    current = JSON.parse(localStorage.getItem(KEY) || "{}");
  } catch {
    current = {};
  }
  if (!current || typeof current !== "object" || Array.isArray(current)) current = {};
  current[event] = (current[event] || 0) + 1;
  try {
    localStorage.setItem(KEY, JSON.stringify(current));
  } catch {
    /* storage is optional */
  }
}

export function readUsage() {
  if (typeof localStorage === "undefined") return {};
  try {
    const parsed = JSON.parse(localStorage.getItem(KEY) || "{}");
    return parsed && typeof parsed === "object" && !Array.isArray(parsed) ? parsed : {};
  } catch {
    return {};
  }
}

export function setUsageOptOut(value) {
  const off = Boolean(value);
  globalThis.__usageOptOut = off;
  if (typeof localStorage === "undefined") return;
  if (off) {
    try { localStorage.removeItem(KEY); } catch { /* storage is optional */ }
    try { localStorage.setItem(OPT_OUT, "1"); } catch { /* storage is optional */ }
  } else {
    try { localStorage.removeItem(OPT_OUT); } catch { /* storage is optional */ }
  }
}

export { usageOptedOut };
